class Solution {
public:
    vector<vector<int>> pathSum(TreeNode* root, int targetSum) {
        vector<vector<int>> result;
        vector<int> current;
        dfs(root, (long long)targetSum, current, result);
        return result;
    }
private:
    void dfs(TreeNode* node, long long remaining, vector<int>& current, vector<vector<int>>& result) {
        if (!node) return;
        current.push_back(node->val);
        remaining -= node->val;
        if (!node->left && !node->right && remaining == 0) {
            result.push_back(current);
        }
        dfs(node->left, remaining, current, result);
        dfs(node->right, remaining, current, result);
        current.pop_back();
    }
};
